+      line-height: 1;
+      letter-spacing: -0.04em;
+    }
+
+    .intro {
+      margin: 0 0 32px;
+      max-width: 60ch;
+      color: var(--muted);
+      font-size: 1.05rem;
+      line-height: 1.7;
+    }
+
+    .faq-list {
+      display: grid;
+      gap: 16px;
+    }
+
+    .example {
+      border: 1px solid rgba(148, 163, 184, 0.2);
+      background: #ffffff;
+      border-radius: var(--radius);
+      overflow: clip;
+      transition: transform 180ms ease, box-shadow 180ms ease, border-color 180ms ease;
+    }
+
+    .example:hover {
+      transform: translateY(-2px);
+      box-shadow: 0 18px 40px rgba(15, 23, 42, 0.08);
+      border-color: rgba(99, 102, 241, 0.22);
+    }
+
+    .question {
+      width: 100%;
+      border: 0;
+      background: transparent;
+      padding: 22px 24px;
+      font: inherit;
+      color: inherit;
+      display: flex;
+      align-items: center;
+      justify-content: space-between;
+      gap: 16px;
+      text-align: left;
+      cursor: pointer;
+    }
+
+    .question span:first-child {
+      font-size: 1.06rem;
+      font-weight: 700;
+      line-height: 1.4;
