+
+    .question:focus-visible {
+      outline: 3px solid rgba(99, 102, 241, 0.28);
+      outline-offset: -3px;
+    }
+
+    .details {
+      display: grid;
+      grid-template-rows: 0fr;
+      transition: grid-template-rows 220ms ease;
+    }
+
+    .details.open {
+      grid-template-rows: 1fr;
+    }
+
+    .details-inner {
+      overflow: hidden;
+    }
+
+    .details p {
+      margin: 0;
+      padding: 0 24px 22px;
+      color: var(--muted);
+      line-height: 1.75;
+    }
+
+    @media (max-width: 640px) {
+      .page {
+        border-radius: 24px;
+      }
+
+      .question {
+        padding: 18px 18px 16px;
+      }
+
+      .details p {
+        padding: 0 18px 18px;
+      }
+    }
+  </style>
+</head>
+<body>
+  <main class="page">
+    <div class="eyebrow">Cat guide</div>
+    <h1>Frequently asked questions about cats</h1>
+    <p class="intro">
+      Learn the basics of cat behavior, care, and communication with a simple FAQ designed like a polished product help center.
+    </p>
+
+    <section class="faq-list" aria-label="Cat frequently asked questions">
+      <div class="example">
+        <button class="question" type="button" aria-expanded="false" aria-controls="answer-1" id="question-1">
+          <span>Why do cats purr?</span>
+          <span class="icon" aria-hidden="true">+</span>
+        </button>
+        <div class="details" id="answer-1" role="region" aria-labelledby="question-1" hidden>
+          <div class="details-inner">
+            <p>Cats often purr when they feel content and safe, but they may also purr to comfort themselves when stressed or recovering. It is a flexible signal that can reflect both happiness and self-soothing.</p>
+          </div>
+        </div>
+      </div>
+
+      <div class="example">
+        <button class="question" type="button" aria-expanded="false" aria-controls="answer-2" id="question-2">
+          <span>How often should I feed my cat?</span>
+          <span class="icon" aria-hidden="true">+</span>
+        </button>
+        <div class="details" id="answer-2" role="region" aria-labelledby="question-2" hidden>
+          <div class="details-inner">
+            <p>Most adult cats do well with measured meals twice a day, while kittens usually need more frequent feeding. The best schedule depends on age, activity, and health, so portion guidance from your veterinarian or food label is a good baseline.</p>
+          </div>
+        </div>
+      </div>
+
+      <div class="example">
+        <button class="question" type="button" aria-expanded="false" aria-controls="answer-3" id="question-3">
+          <span>Why does my cat knead blankets or my lap?</span>
+          <span class="icon" aria-hidden="true">+</span>
+        </button>
+        <div class="details" id="answer-3" role="region" aria-labelledby="question-3" hidden>
+          <div class="details-inner">
+            <p>Kneading starts in kittenhood during nursing and often stays as a comfort behavior in adulthood. Cats usually knead when they feel relaxed, secure, and attached to a favorite person or cozy space.</p>
+          </div>
+        </div>
+      </div>
+
+      <div class="example">
+        <button class="question" type="button" aria-expanded="false" aria-controls="answer-4" id="question-4">
+          <span>Do indoor cats still need enrichment?</span>
+          <span class="icon" aria-hidden="true">+</span>
+        </button>
+        <div class="details" id="answer-4" role="region" aria-labelledby="question-4" hidden>
+          <div class="details-inner">
+            <p>Yes. Indoor cats benefit from climbing spots, scratching posts, window views, toys, and short play sessions that mimic hunting. Enrichment helps prevent boredom and supports healthy exercise and behavior.</p>
+          </div>
+        </div>
+      </div>
+
+      <div class="example">
+        <button class="question" type="button" aria-expanded="false" aria-controls="answer-5" id="question-5">
+          <span>What does a slowly blinking cat mean?</span>
+          <span class="icon" aria-hidden="true">+</span>
+        </button>
+        <div class="details" id="answer-5" role="region" aria-labelledby="question-5" hidden>
+          <div class="details-inner">
+            <p>A slow blink is usually a sign of trust and calm body language. Many people think of it as a cat's version of a friendly smile, and you can often return the gesture to reinforce that relaxed connection.</p>
+          </div>
+        </div>
+      </div>
+    </section>
+  </main>
+
+  <script>
+    const questions = document.querySelectorAll(".question");
+
+    questions.forEach((button) => {
+      button.addEventListener("click", () => {
+        const details = document.getElementById(button.getAttribute("aria-controls"));
+        const isOpen = button.getAttribute("aria-expanded") === "true";
+
+        button.setAttribute("aria-expanded", String(!isOpen));
+        details.hidden = isOpen;
+        details.classList.toggle("open", !isOpen);
+      });
+    });
+  </script>
+</body>
+</html>
*** End Patch
