      flex: 0 0 auto;
      width: 36px;
      height: 36px;
      border-radius: 50%;
      display: grid;
      place-items: center;
      background: rgba(99, 102, 241, 0.1);
      color: var(--accent-strong);
      transition: transform 180ms ease, background-color 180ms ease;
